function cursor(x,y,click=false){return `<g transform="translate(${x} ${y})" filter="url(#cursorShadow)"><path d="M0 0L2 30L10 23L16 36L23 32L17 20L28 19Z" fill="#26352f" stroke="#ffffff" stroke-width="2"/></g>${click?circle(x+4,y+5,23,'none',`stroke="${C.orange}" stroke-width="2.5" opacity="0.7"`):''}`}
function stateAt(t){const q=((t%30)+30)%30,scene=sceneAt(t);if(scene==='Map')return {scene,mapSelected:q>=3.3,mapZoom:ease((q-3.3)/2.5),panelProgress:ease((q-6.1)/.9),week:q>=12.2?'2026W42':q>=11.4?'2026W41':'2026W40',indicator:q>=18.6?'water':'clinical',weekMenu:false};if(scene==='Query')return {scene,week:q>=8?'2026W40':'2026W39',horizon:2,score:'clipped',queryReady:q>=17,queryLoading:q>=16&&q<17,evidence:q>=19&&q<23,weekMenu:q>=5&&q<8,horizonMenu:q>=11&&q<13,exported:q>=21&&q<23.7};if(scene==='Data')return {scene,dataYear:q<7?'all':q<21?'2026':'2024',dataScale:q>=13?'log':'raw',dataView:q>=23?'table':'charts',dataYearMenu:q>=5&&q<7||q>=19&&q<21,dataScrollOffset:q>=26?ease((q-26)/2)*140:0};if(scene==='Models')return {scene,modelView:q<14?'ridge':q<18?'clusters':'lof',week:'2026W40',patternWeek:q>=21?'2026W5':'2026W40',patternWeekMenu:q>=19.5&&q<21,neighborsOpen:q>=25};if(scene==='Evaluation')return {scene,score:q>=10&&q<19?'raw':'clipped',horizon:2,block:q>=24?8:4,exported:q>=27};return {scene,exportDataset:q<8?'weekly':q<19?'forecasts':'comparison',exportMenu:q>=5&&q<8||q>=17&&q<19,exported:q>=25&&q<29.5,week:'2026W40',horizon:2,score:'clipped'}}
