function pointer(t){const points=cursorTracks[sceneAt(t)],q=t%30;let previous=points[0];for(let i=1;i<points.length;i++){const next=points[i];if(q<next[0]){const p=ease((q-(next[0]-.55))/.55);return [lerp(previous[1],next[1],p),lerp(previous[2],next[2],p),Boolean(next[3]&&q>next[0]-.12)]}previous=next}return[previous[1],previous[2],false]}
